# test_rgb_to_hex.py

import pytest

from your_module import rgb_to_hex  # Replace "your_module" with the actual module name


@pytest.mark.parametrize(
    ("r", "g", "b", "expected"),
    [
        (255, 0, 0, "#ff0000"),
        (0, 255, 0, "#00ff00"),
        (0, 0, 255, "#0000ff"),
        (12, 34, 56, "#0c2238"),
        (171, 205, 239, "#abcdef"),
    ],
)
def test_rgb_to_hex_happy_path(r, g, b, expected):
    assert rgb_to_hex(r, g, b) == expected


@pytest.mark.parametrize(
    ("r", "g", "b", "expected"),
    [
        (0, 0, 0, "#000000"),
        (255, 255, 255, "#ffffff"),
        (0, 15, 16, "#000f10"),  # verifies zero-padding
    ],
)
def test_rgb_to_hex_edge_cases(r, g, b, expected):
    assert rgb_to_hex(r, g, b) == expected


@pytest.mark.parametrize(
    ("r", "g", "b"),
    [
        (-1, 0, 0),
        (0, -1, 0),
        (0, 0, -1),
        (256, 0, 0),
        (0, 256, 0),
        (0, 0, 256),
    ],
)
def test_rgb_to_hex_raises_value_error_for_out_of_range_values(r, g, b):
    with pytest.raises(ValueError, match="RGB values must be 0-255"):
        rgb_to_hex(r, g, b)


@pytest.mark.parametrize(
    "args",
    [
        ("0", 0, 0),
        (0, None, 0),
        (0, 0, object()),
        (1.5, 2, 3),
    ],
)
def test_rgb_to_hex_raises_for_non_integer_values(args):
    with pytest.raises((TypeError, ValueError)):
        rgb_to_hex(*args)


@pytest.mark.parametrize(
    "args",
    [
        (0, 0),
        (0, 0, 0, 0),
    ],
)
def test_rgb_to_hex_requires_exactly_three_arguments(args):
    with pytest.raises(TypeError):
        rgb_to_hex(*args)
